def min_chars_to_transmit(route):
    n = len(route)
    dp = [[n] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        dp[i][0] = i
        dp[0][i] = i

        for j in range(1, min(i, n) + 1):
            dp[i][j] = min(dp[i][j], dp[i - j][j] + 1)
            if route[i - 1] == 'M':
                dp[i][j] = min(dp[i][j], dp[i - j][j - 1] + 2)

