def solve(n, k, a):
    result = [0] * n
    i = 0
    while i < n:
        max_index = i
        for j in range(1, k + 1):
            if i - j >= 0 and a[i - j] > a[max_index]:
                max_index = i - j
            if i + j < n and a[i + j] > a[max_index]:
                max_index = i + j
        for j in range(2 * k + 1):
            result[(i + j) % n] = (j % 2) + 1
        i += 2 * k + 1
    return ''.join(map(str, result))

