def sort_matrix(n, m, matrix):
    rows = [0] * n
    cols = [0] * m

    for i in range(n):
        for j in range(m):
            if (i + j) % 2 == 1 and matrix[i][j] != 0:
                rows[i] ^= 1
                cols[j] ^= 1

    sorted_matrix = [[matrix[i][j] ^ rows[i] ^ cols[j] for j in range(m)] for i in range(n)]

    return sorted_matrix

